use noworodek::{ArchitectureId,DType,ExternalTransformer,MemoryWeightBackend,ParameterHandle,TensorSpec,TinyTransformerConfig,WeightSetHeader,WeightSetId,WeightSetManager,WeightSetManifest,WeightSetVersion};
use noworodek::model::transformer_backprop::train_step_ce;
fn vals(n:usize,s:f32,p:f32)->Vec<f32>{(0..n).map(|i|s*(((i as f32+p)*0.37).sin())).collect()}
fn build()->(WeightSetManager,ExternalTransformer){let(v,h,i)=(8usize,4usize,8usize);let specs=vec![TensorSpec::new("model.embeddings.token.weight",vec![v,h],DType::F32,"bp"),TensorSpec::new("model.layers.00.attention.q_proj.weight",vec![h,h],DType::F32,"bp"),TensorSpec::new("model.layers.00.attention.k_proj.weight",vec![h,h],DType::F32,"bp"),TensorSpec::new("model.layers.00.attention.v_proj.weight",vec![h,h],DType::F32,"bp"),TensorSpec::new("model.layers.00.attention.o_proj.weight",vec![h,h],DType::F32,"bp"),TensorSpec::new("model.layers.00.mlp.up_proj.weight",vec![h,i],DType::F32,"bp"),TensorSpec::new("model.layers.00.mlp.gate_proj.weight",vec![h,i],DType::F32,"bp"),TensorSpec::new("model.layers.00.mlp.down_proj.weight",vec![i,h],DType::F32,"bp"),TensorSpec::new("model.layers.00.attention_norm.weight",vec![h],DType::F32,"bp"),TensorSpec::new("model.layers.00.mlp_norm.weight",vec![h],DType::F32,"bp"),TensorSpec::new("model.final_norm.weight",vec![h],DType::F32,"bp"),TensorSpec::new("model.lm_head.weight",vec![v,h],DType::F32,"bp")];let m=WeightSetManifest::new(WeightSetHeader::new(WeightSetId::new("transformer-backprop-v1"),WeightSetVersion::new("0.1.0").unwrap(),ArchitectureId::new("noworodek-decoder-v0")).with_capabilities(["externalized-parameters","observable","editable","analytic-backprop"]).with_provenance("NOWORODEK real-transformer CE backprop v1"),specs).unwrap();let data=[("model.embeddings.token.weight",vals(v*h,0.20,0.0)),("model.layers.00.attention.q_proj.weight",vals(h*h,0.30,1.0)),("model.layers.00.attention.k_proj.weight",vals(h*h,0.22,2.0)),("model.layers.00.attention.v_proj.weight",vals(h*h,0.18,3.0)),("model.layers.00.attention.o_proj.weight",vals(h*h,0.16,4.0)),("model.layers.00.mlp.up_proj.weight",vals(h*i,0.12,5.0)),("model.layers.00.mlp.gate_proj.weight",vals(h*i,0.11,6.0)),("model.layers.00.mlp.down_proj.weight",vals(i*h,0.10,7.0)),("model.layers.00.attention_norm.weight",vec![1.0;h]),("model.layers.00.mlp_norm.weight",vec![1.0;h]),("model.final_norm.weight",vec![1.0;h]),("model.lm_head.weight",vals(v*h,0.15,8.0))];let mut mgr=WeightSetManager::new(ArchitectureId::new("noworodek-decoder-v0"));let id=mgr.mount(Box::new(MemoryWeightBackend::with_tensor_data(m,data))).unwrap();let model=ExternalTransformer::new(TinyTransformerConfig{vocab_size:v,hidden_size:h,intermediate_size:i,sequence_length:8,num_layers:1,rms_norm_eps:1e-5},id);(mgr,model)}
fn main(){let tokens=[0usize,1,2];let target=3usize;let(mgr0,model)=build();let mut mgr=mgr0;let before=model.forward(&mgr,&tokens).unwrap();let h=model.config.hidden_size;let v=model.config.vocab_size;let row=&before.values()[(tokens.len()-1)*v..tokens.len()*v];let m=row.iter().copied().fold(f32::NEG_INFINITY,f32::max);let z:f32=row.iter().map(|x|(*x-m).exp()).sum();let before_loss=-((row[target]-m).exp()/z.max(f32::MIN_POSITIVE)).ln();let names=["model.layers.00.attention.q_proj.weight","model.layers.00.attention.k_proj.weight","model.layers.00.attention.v_proj.weight","model.layers.00.attention.o_proj.weight","model.layers.00.mlp.gate_proj.weight","model.layers.00.mlp.up_proj.weight","model.layers.00.mlp.down_proj.weight","model.layers.00.attention_norm.weight","model.layers.00.mlp_norm.weight","model.final_norm.weight","model.lm_head.weight","model.embeddings.token.weight"];let initial:Vec<Vec<f32>>=names.iter().map(|n|ParameterHandle::new(model.weight_set.clone(),*n).unwrap().read(&mgr).unwrap().values().to_vec()).collect();println!("NOWORODEK REAL TRANSFORMER BACKPROP V1");println!("experience_id=math.next_token.real-backprop-v1 target={} steps=40 lr=0.01",target);println!("BEFORE loss={:.9}",before_loss);let mut last=before_loss;for step in 0..40{let r=train_step_ce(&model,&mut mgr,&tokens,target,0.01).unwrap();last=r.loss_after;if step==0||step%10==9{println!("step={} loss_before={:.9} loss_after={:.9} grad_l2={:.9} changed_tensors={}",step+1,r.loss_before,r.loss_after,r.gradient_l2,r.changed_tensors);}}let after=model.forward(&mgr,&tokens).unwrap();let row=&after.values()[(tokens.len()-1)*v..tokens.len()*v];let m=row.iter().copied().fold(f32::NEG_INFINITY,f32::max);let z:f32=row.iter().map(|x|(*x-m).exp()).sum();let after_loss=-((row[target]-m).exp()/z.max(f32::MIN_POSITIVE)).ln();println!("AFTER loss={:.9} loss_reduction={:.9}",after_loss,before_loss-after_loss);for(n,old)in names.iter().zip(initial.iter()){let cur=ParameterHandle::new(model.weight_set.clone(),*n).unwrap().read(&mgr).unwrap();let maxd=old.iter().zip(cur.values()).map(|(a,b)|(*a-*b).abs()).fold(0.0f32,f32::max);let l2=(old.iter().zip(cur.values()).map(|(a,b)|{let d=*a-*b;d*d}).sum::<f32>()).sqrt();println!("DELTA tensor={} l2={:.9} max_abs={:.9}",n,l2,maxd);}println!("RESULT real_analytic_backprop=true final_loss={:.9}",last);let _=h;}
